# Function to check if a song matches any old song
def matches_old(song_id):
    song = song_details[song_id]
    song_title = song['title'].lower()
    song_artists = {a['name'].lower() for a in song['artists']}
    for old_title, old_artists in old_songs_norm:
        if song_title == old_title and song_artists == old_artists:
            return True
    return False

# Identify songs to remove per playlist and collect all matching song_ids
songs_to_remove = {}  # playlist_id -> list of song_ids
all_matching_song_ids = set()
for pid, songs in playlists_songs.items():
